CREATE OR REPLACE FUNCTION public.trade_in_requires_evaluation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _eid uuid:=public.safe_uuid(current_setting('mli.evaluation_id',true)); _e public.evaluations; _client uuid; BEGIN IF _eid IS NULL THEN RETURN NEW; END IF; SELECT * INTO _e FROM public.evaluations WHERE id=_eid FOR UPDATE; IF NOT FOUND OR _e.store_id<>NEW.store_id THEN RAISE EXCEPTION 'Avaliação não pertence à loja.'; END IF; SELECT client_id INTO _client FROM public.sales WHERE id=NEW.sale_id AND store_id=NEW.store_id; IF _e.client_id IS NULL OR _client IS NULL OR _e.client_id<>_client THEN RAISE EXCEPTION 'A avaliação pertence a outro cliente.'; END IF; IF _e.status='utilizada' OR _e.sale_id IS NOT NULL THEN RAISE EXCEPTION 'Avaliação já utilizada.'; END IF; UPDATE public.evaluations SET status='utilizada',sale_id=NEW.sale_id WHERE id=_eid; RETURN NEW; END $$;
COMMENT ON FUNCTION public.trade_in_requires_evaluation() IS 'Optional evaluation linkage only; authorized manual trade-ins do not require approval. Original evaluation values remain preserved.';